// IDC (Ideographic Description Character) operators: arity + a short,
// human-readable description used for the hover tooltip.
export const OPERATORS = {
  "⿰": { arity: 2, label: "left / right" },
  "⿱": { arity: 2, label: "top / bottom" },
  "⿴": { arity: 2, label: "full enclosure" },
  "⿵": { arity: 2, label: "enclosure from above" },
  "⿶": { arity: 2, label: "enclosure from below" },
  "⿷": { arity: 2, label: "enclosure from left" },
  "⿸": { arity: 2, label: "enclosure from upper-left" },
  "⿹": { arity: 2, label: "enclosure from upper-right" },
  "⿺": { arity: 2, label: "enclosure from lower-left" },
  "⿻": { arity: 2, label: "overlay" },
  "⿲": { arity: 3, label: "left / middle / right" },
  "⿳": { arity: 3, label: "top / middle / bottom" },
};

export const DEFAULT_CHARACTER = "警";
